import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), x = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Features packed as price * 2^17 + index so one primitive sort orders them by price.
        long[] features = new long[m];
        for (int j = 0; j < m; j++) features[j] = nextLong() << 17 | j;
        Arrays.sort(features);
        // Incompatible pairs packed as plan * m + feature, sorted for binary search.
        long[] bad = new long[x];
        for (int t = 0; t < x; t++) bad[t] = (nextLong() - 1) * m + (nextLong() - 1);
        Arrays.sort(bad);
        // Each plan takes the first compatible feature by price; every skip uses up a distinct bad pair.
        long answer = 0, mask = (1L << 17) - 1;
        for (int i = 0; i < n; i++)
            for (int t = m - 1; t >= 0; t--) {
                long j = features[t] & mask;
                if (Arrays.binarySearch(bad, (long) i * m + j) < 0) {
                    answer = Math.max(answer, a[i] + (features[t] >> 17));
                    break;
                }
            }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, x := nextInt(), nextInt(), nextInt()
	a, b := make([]int, n), make([]int, m)
	for i := range a {
		a[i] = nextInt()
	}
	for j := range b {
		b[j] = nextInt()
	}
	// Incompatible pairs packed as plan * m + feature, sorted for binary search.
	bad := make([]int, x)
	for t := range bad {
		i, j := nextInt()-1, nextInt()-1
		bad[t] = i*m + j
	}
	sort.Ints(bad)
	order := make([]int, m)
	for j := range order {
		order[j] = j
	}
	sort.Slice(order, func(p, q int) bool { return b[order[p]] > b[order[q]] })
	// Each plan takes the first compatible feature by price; every skip uses up a distinct bad pair.
	answer := 0
	for i := 0; i < n; i++ {
		for _, j := range order {
			key := i*m + j
			t := sort.SearchInts(bad, key)
			if t == len(bad) || bad[t] != key {
				answer = max(answer, a[i]+b[j])
				break
			}
		}
	}
	fmt.Println(answer)
}
